 function __construct($owner){$this->inner=$owner;$this->db_connect_id=$owner->db_connect_id;}
 function __call($name,$args){return call_user_func_array(array($this->inner,$name),$args);}
 function sql_query($sql,$transaction=false){if(preg_match('/^(?:INSERT INTO fixture_confirm\b|DELETE FROM fixture_confirm\b|DELETE c FROM fixture_confirm\b)/D',$sql)){return$this->inner->inner->sql_query($sql,$transaction);}return$this->inner->sql_query($sql,$transaction);}
 function sql_close(){try{return$this->inner->sql_close();}finally{$this->db_connect_id=null;}}
}
